update product
category_id = #{categoryId}, name = #{name}, subtitle = #{subtitle}, sort = #{sort}, image = #{image}, description = #{description}, status = #{status}, trace_enabled = #{traceEnabled}, update_time = #{updateTime}, update_user = #{updateUser}
where id = #{id}

mapper.select:
select p.*, c.name as categoryName from product p left join category c on p.category_id = c.id
and p.name like concat('%', #{name}, '%')
and p.category_id = #{categoryId}
and p.status = #{status}
order by p.create_time desc

select * from product


        and category_id = #{categoryId}


        and name like concat('%', #{name}, '%')


        and status = #{status}


order by sort desc, create_time desc
